import sys

def minimumSum(S):
    n = len(S)
    S = list(S)
    for i in range(n // 2):
        if S[i] == '?' and S[n - i - 1] == '?':
            S[i] = S[n - i - 1] = 'a'
        elif S[i] == '?':
            S[i] = S[n - i - 2] if i > 0 and S[n - i - 2] != '?' else S[n - i]
        elif S[n - i - 1] == '?':
            S[n - i - 1] = S[i + 1] if i < n - 1 and S[i + 1] != '?' else S[i]
        if S[i] != S[n - i - 1]:
            return -1
    return sum(abs(ord(S[i]) - ord(S[i + 1])) for i in range(n - 1))

input = sys.stdin.read().strip()
print(minimumSum(input))
